import{_ as s,l as o,o as e,c as l,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"带宽时延积","description":"","frontmatter":{"title":"带宽时延积","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bandwidth-delay-product.md","filePath":"cs/bandwidth-delay-product.md","lastUpdated":1789023840000}'),h={name:"cs/bandwidth-delay-product.md"};function m(B,a,T,P,E,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="带宽时延积" tabindex="-1">带宽时延积 <a class="header-anchor" href="#带宽时延积" aria-label="Permalink to &quot;带宽时延积&quot;">​</a></h1><div class="epigraph"><p>管道里要装满 $C\\times\\mathrm{RTT}$ 的飞行字节才吃饱链路；窗口上限小于 BDP 时，AIMD 再公平也达不到 $C$。</p><footer>—— 据 Kleinrock 管道直觉；Kurose and Ross 延迟带宽积；RFC 1072 / 7323 动机整理</footer></div><p><a href="/cs/satellite-latency">卫星</a> 已点名 BDP。<a href="/cs/fast-retransmit-recovery">上一课</a> 的快恢复要 FlightSize。<a href="/cs/tcp-window">TCP 窗口</a> 的 16 比特字段未放大。缺口是<strong>把 BDP 写成硬约束</strong>：窗口、缓冲、初始窗口。本课不把窗口缩放选项写完，下一课写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>速率 \\(C\\)、往返 \\(\\mathrm{RTT}\\)，未确认字节需约 \\(C\\times\\mathrm{RTT}\\)。1 Gb/s × 100 ms = 12.5 MB，远超默认 64 KiB 窗口。数据中心 25 Gb × 10 μs 反而很小，incast 是瞬态不是 BDP。瓶颈缓冲：理论一 BDP 量级配合 MD，过小则锯齿碰空，过大则后课 bufferbloat。</p><p>不要把 BDP 写成「必须配置的内核参数名」，它是几何量。</p><p><span class="marginnote">Kleinrock 长肥管道。RFC 7323 为此扩大窗口。本课公式，选项下一课。</span></p><h3 id="窗口几何量" tabindex="-1">窗口几何量 <a class="header-anchor" href="#窗口几何量" aria-label="Permalink to &quot;窗口几何量&quot;">​</a></h3><p>飞行 ≥ \\(C\\times\\)RTT 才吃饱。小 MSS 使填满更慢。缓冲与 BDP 同量级是经典折中，过深则膨胀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算两例：局域网 vs 跨洋 vs 卫星。对照 rwnd 与 cwnd：有效窗口 \\(\\min\\) 两者，再与 BDP 比。画管道：链路上的比特 = 带宽 × 单向延迟，往返则乘二（近似）。</p>',11)),(e(),d(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%93%B6%E9%A2%88%E9%80%9F%E7%8E%87%22%5D%20--%3E%20BDP%5B%22C%20%E4%B9%98%20RTT%22%5D%0A%20%20RTT%5B%22%E5%BE%80%E8%BF%94%E6%97%B6%E5%BB%B6%22%5D%20--%3E%20BDP%0A%20%20BDP%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E8%87%B3%E5%B0%91%E8%BF%99%E4%B9%88%E5%A4%A7%22%5D%0A%20%20WIN%20--%3E%20OPT%5B%22%E9%9C%80%E8%A6%81%E7%BC%A9%E6%94%BE%E9%80%89%E9%A1%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AIMD 每 RTT 加一 MSS，填满 BDP 要约 BDP/MSS 个 RTT，长肥管道慢启动必须指数阶段帮一把。PMTUD 失败导致小 MSS，填满更慢。RoCE 用信用/PFC 填管道，不靠 cwnd 名，但几何相同。</p><p>测量：iperf 后课；这里只要承认窗口是 BDP 的操作化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入带宽估计滤波器。窗口缩放与时间戳是下一课。后课默认：吃饱链路 ⇔ 飞行 ≥ BDP（再加队列目标）。</p><p>应用自己再缓冲一层不增加 \\(C\\)，只加延迟。</p><p>上一课留下的缺口在本课收口；「带宽时延积」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/window-scale-timestamps">窗口缩放与时间戳</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BDP \\(=C\\times\\mathrm{RTT}\\) 是飞行字节目标。</li><li>小窗口或小 MSS 喂不饱长肥管道。</li><li>缓冲与 BDP 同量级是经典折中。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Kurose and Ross；RFC 7323 动机。</li></ul>',10))])}const f=s(h,[["render",m]]);export{D as __pageData,f as default};
